func TestForgeMirrorHint(t *testing.T) {
	t.Parallel()

	t.Run("names the github repo from origin", func(t *testing.T) {
		t.Parallel()
		dir := initRepoWithRemotes(t, map[string]string{"origin": "https://github.com/OctoCat/Hello-World"})
		owner, repo, ok := forgeMirrorHint(t.Context(), dir)
		require.True(t, ok)
		require.Equal(t, "octocat", owner)
		require.Equal(t, "hello-world", repo)
	})

	t.Run("false for a non-github remote", func(t *testing.T) {
		t.Parallel()
		dir := initRepoWithRemotes(t, map[string]string{"origin": "git@gitlab.com:acme/app.git"})
		_, _, ok := forgeMirrorHint(t.Context(), dir)
		require.False(t, ok)
	})

	t.Run("false when already a mirror", func(t *testing.T) {
		t.Parallel()
		dir := initRepoWithRemotes(t, map[string]string{"origin": testMirrorURL})
		_, _, ok := forgeMirrorHint(t.Context(), dir)
		require.False(t, ok, "an entire:// remote is a mirror, not a mirror candidate")
	})

	t.Run("false with no remotes", func(t *testing.T) {
		t.Parallel()
		dir := initRepoWithRemotes(t, nil)
		_, _, ok := forgeMirrorHint(t.Context(), dir)
		require.False(t, ok)
	})
}

func TestFormatMirrorHint(t *testing.T) {
	t.Parallel()
	sty := newStatusStyles(&bytes.Buffer{})
	out := formatMirrorHint("octocat", "hello-world", sty)
	require.Contains(t, out, "not mirrored")
	require.Contains(t, out, "entire repo mirror create github.com/octocat/hello-world")
}

