854	func runTrailCreate(cmd *cobra.Command, title, body, base, branch, statusStr, typeStr, priorityStr string, assignees []string, checkout, noBranch bool) error {
855		ctx := cmd.Context()
856		w := cmd.OutOrStdout()
857		errW := cmd.ErrOrStderr()
858	
859		if err := validateTrailCreateFlagCombos(cmd, checkout, noBranch); err != nil {
860			return err
861		}
862		if cmd.Flags().Changed("type") {
863			if !trail.Type(strings.TrimSpace(typeStr)).IsValid() {
864				return fmt.Errorf("invalid type %q: valid values are %s", typeStr, formatValidTypes())
865			}
866		}
867		if cmd.Flags().Changed("priority") {
868			if !trail.Priority(strings.TrimSpace(priorityStr)).IsValid() {
869				return fmt.Errorf("invalid priority %q: valid values are %s", priorityStr, formatValidPriorities())
870			}
871		}
872	
873		repo, err := strategy.OpenRepository(ctx)
874		if err != nil {
875			return fmt.Errorf("failed to open repository: %w", err)
876		}
877		defer repo.Close()
878	
879		base = resolveTrailCreateBase(repo, base)
880		_, currentBranch, _ := isOnDefaultBranchRepo(repo) //nolint:errcheck // best-effort; reuse the open repo for the current branch name
881		title, body, base, branch, statusStr, err = resolveTrailCreateFields(cmd, w, title, body, base, branch, statusStr, currentBranch, noBranch)
882		if err != nil {
